interface AppProps {
  title: string;
  version: number;
}
export const App = ({ title, version }: AppProps) => (
  <main className="min-h-screen p-8 text-foreground">
    <h1>{title} v{version}</h1>
  </main>
);

export function UserProfile({ userId }: { userId: string }) {
  const [user, setUser] = useState<User | null>(null);
  useEffect(() => { fetchUser(userId).then(setUser); }, [userId]);
  return <div>{user ? <h1>{user.name}</h1> : <p>Loading...</p>}</div>;
}

// Next.js Server Action with Mutation
'use server';
import { db } from '@/lib/db';

export async function updateUsername(userId: string, newName: string) {
  await db.user.update({ where: { id: userId }, data: { name: newName } });
}

// Drizzle ORM Schema & Query
import { pgTable, serial, text, varchar } from 'drizzle-orm/pg-core';
export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  fullName: text('full_name'),
  phone: varchar('phone', { length: 256 }),
});

import Redis from 'ioredis';
const redis = new Redis(process.env.REDIS_URL!);
await redis.set('active:users', '1420', 'EX', 300);

// Multi-region deployment configuration
export const runtime = 'edge';
export async function GET() {
  return new Response(JSON.stringify({ region: process.env.VERCEL_REGION }));
}
